import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`media-outreach-list`,heroTitle:`Build your media outreach list in minutes`,heroSubtitle:`Perplexity Computer researches relevant journalists, finds verified contact details, and delivers a targeted media list — automatically.`,inputUrlCta:`Build my media list`,inputUrlPlaceholder:`yourbrand.com`,inputUrlPrefill:`Go to {url} and build a comprehensive media outreach list for this company or brand. 1) Analyze the site to identify the brand's industry, key topics, recent news, and target audience. 2) Research journalists, reporters, editors, and bloggers who actively cover this industry and these topics — prioritize writers who have published relevant articles in the last 6 months. 3) For each contact, find their full name, outlet, beat/focus area, email address, social media handles (Twitter/X, LinkedIn), and a link to their most recent relevant article. 4) Score each contact's relevance to the brand on a 1-10 scale based on beat alignment, outlet reach, and recency of coverage. 5) Organize contacts into tiers: Tier 1 (top-priority, highly relevant national/industry outlets), Tier 2 (strong fit, mid-tier outlets), Tier 3 (niche or emerging voices). 6) Deliver a spreadsheet with columns for: name, outlet, beat, email, Twitter/X, LinkedIn, most recent relevant article URL, relevance score, and tier. Include at least 50 contacts across all tiers.`,heroOverlaySteps:[`Analyzing your brand's industry, topics, and recent news`,`Researching journalists and editors who cover your space`,`Verifying contact details and scoring relevance for each journalist`,`Tiered media list with contacts, beats, and relevance scores — ready to pitch`],generatingSteps:[`Visiting {url} to extract your brand positioning, industry, and key topics`,`Designing an agent to research journalists, editors, and bloggers covering your space`,`Configuring contact verification, relevance scoring, and tier classification`,`Setting up your media list spreadsheet with 50+ prioritized contacts`],featureSectionTitle:`From URL to targeted media list`,featureCardTitles:[`Connects to your PR stack`,`Outputs you can pitch with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Gmail, Notion, Airtable, Slack — Computer plugs into your tools so your media list flows straight into outreach workflows.`,`Tiered journalist lists. Verified emails and socials. Beat-matched relevance scores. Recent article links. A ready-to-use spreadsheet you can load into any outreach tool.`],capabilitySectionTitle:`Your PR researcher, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a pitch-ready media list.`,capabilityCards:[{title:`Journalist Research`,description:`Computer can find reporters, editors, and bloggers who actively cover your industry — filtering by beat, outlet tier, and recency of coverage.`},{title:`Contact Verification`,description:`Computer can track down verified email addresses, Twitter/X handles, and LinkedIn profiles for every journalist on your list.`},{title:`Relevance Scoring`,description:`Computer can score each contact's fit to your brand based on beat alignment, outlet reach, and how recently they covered your space.`},{title:`Connect Your Tools`,description:`Computer can export directly to Google Sheets, Airtable, Notion, and Gmail — build workflows across your entire PR and communications stack.`},{title:`Remember & Learn`,description:`Computer can remember your past pitches, preferred outlets, and journalist relationships across sessions — so every list gets smarter over time.`},{title:`Monitor & Alert`,description:`Computer can track when journalists change beats or outlets, and flag new reporters covering your industry so your list stays current.`}]});export{t as default};
